    private BigDecimal calcularDescontoCupom(String cupom, List<Item> itens, BigDecimal subtotalComDesconto) {
        if (cupom == null || cupom.isEmpty() || "FRETEGRATIS".equals(cupom) || "LEVE3PAGUE2".equals(cupom)) {
