        };
    }

    private PaymentAdjustment calcularAjustePagamento(String formaPagamento, int parcelas, BigDecimal totalPedido) {
        return switch (formaPagamento) {
            case "PIX" -> {
                BigDecimal desconto = totalPedido.multiply(new BigDecimal("0.05"));
