        BigDecimal descontoCupom = calcularDescontoCupom(cupom, itens, subtotalProdutos);

        // Calcula frete
        ShippingInfo shippingInfo = calcularFrete(modalidadeEntrega, itens);
        BigDecimal frete = shippingInfo.custo;
